configuration.msdyn_mashupscript:
section Section1;

shared Query =
    let
        Source =
            Table.FromRows(
                Json.Document(
                    Binary.Decompress(
                        Binary.FromText(
                            "
    
    
    
    ",
                            BinaryEncoding.Base64
                        ),
                        Compression.Deflate
                    )
                ),
                let
                    _t = ((type nullable text)
                    meta
                    [
                        Serialized.Text = true
                    ])
                in
                    type table [
                        Column1 = _t,
                        Column2 = _t,
                        Column3 = _t,
                        Column4 = _t,
                        Column5 = _t,
                        Column6 = _t
                    ]
            ),
        #"Promoted headers" =
            Table.PromoteHeaders(
                Source,
                [PromoteAllScalars = true]
            ),
        #"Changed column type" =
            Table.TransformColumnTypes(
                #"Promoted headers",
                {
                    {
                        "Location",
                        type text
                    },
                    {
                        "Role",
                        type text
                    },
                    {
                        "Resource",
                        type text
                    },
                    {
                        "StartTimestamp",
                        type datetime
                    },
                    {
                        "CaseId",
                        Int64.Type
                    },
                    {
                        "ActivityName",
                        type text
                    }
                }
            )
    in
        #"Changed column type";
